			["triggers"] = {
				{
					["trigger"] = {
						["type"] = "custom",
						["custom_type"] = "status",
						["unit"] = "player",
						["event"] = "Health",
						["names"] = {
						},
						["spellIds"] = {
						},
						["customName"] = "function() return aura_env.names or \"Missing Mark\" end",
						["custom"] = "function()\n\n    if select(2, UnitClass(\"player\")) ~= \"DRUID\" then return false end\n    local now = GetTime()\n    if aura_env.nextCheck and now < aura_env.nextCheck then return aura_env.missing end\n    aura_env.nextCheck = now + 0.25\n    local mark = GetSpellInfo(1126)\n    local gift = GetSpellInfo(21849)\n    local function covered(unit)\n        for i = 1, 40 do\n            local name = UnitBuff(unit, i)\n            if not name then break end\n            if name == mark or name == gift then return true end\n        end\n        return false\n    end\n\n    local names = {}\n    local raid = GetNumRaidMembers() > 0\n    local count = raid and GetNumRaidMembers() or GetNumPartyMembers()\n    for i = 1, count do\n        local unit = (raid and \"raid\" or \"party\") .. i\n        if UnitExists(unit) and not UnitIsUnit(unit, \"player\")\n            and UnitIsConnected(unit) and not UnitIsDeadOrGhost(unit)\n            and UnitIsVisible(unit) and not covered(unit) then\n            local name = UnitName(unit) or unit\n            if mark and IsSpellInRange(mark, unit) == 0 then name = name .. \" (range)\" end\n            names[#names + 1] = name\n        end\n    end\n    table.sort(names)\n    local lines = {}\n    for i = 1, #names, 3 do\n        lines[#lines + 1] = table.concat(names, \", \", i, math.min(i + 2, #names))\n    end\n    aura_env.names = \"Missing Mark: \" .. #names .. \"\\n\" .. table.concat(lines, \"\\n\")\n    aura_env.missing = #names > 0\n    return aura_env.missing\nend",
						["customIcon"] = "function() return select(3, GetSpellInfo(1126)) end",
						["check"] = "update",
						["subeventSuffix"] = "_CAST_START",
