			["preferToUpdate"] = false,
			["yOffset"] = -84,
			["anchorPoint"] = "CENTER",
			["cooldownEdge"] = false,
			["icon"] = true,
			["triggers"] = {
				{
					["trigger"] = {
						["type"] = "custom",
						["custom_type"] = "status",
						["names"] = {
						},
						["event"] = "Health",
						["unit"] = "player",
						["subeventPrefix"] = "SPELL",
						["customName"] = "function() return \"Faerie Fire missing\" end",
						["custom"] = "function()\n    if select(2, UnitClass(\"player\")) ~= \"DRUID\"\n        or UnitIsDeadOrGhost(\"player\") or not UnitExists(\"target\")\n        or UnitIsDeadOrGhost(\"target\") or not UnitCanAttack(\"player\", \"target\") then\n        aura_env.missing = false\n        return false\n    end\n    local guid = UnitGUID(\"target\")\n    local now = GetTime()\n    if aura_env.targetGUID == guid and aura_env.nextCheck and now < aura_env.nextCheck then\n        return aura_env.missing\n    end\n    aura_env.targetGUID = guid\n    aura_env.nextCheck = now + 0.25\n    local normal = GetSpellInfo(770)\n    local feral = GetSpellInfo(16857)\n    for i = 1, 40 do\n        local name = UnitDebuff(\"target\", i)\n        if not name then break end\n        if name == normal or name == feral then\n            aura_env.missing = false\n            return false\n        end\n    end\n    aura_env.missing = true\n    return true\nend",
						["customIcon"] = "function() return select(3, GetSpellInfo(770)) end",
